CREATE TABLE requirement_actions(requirement_id TEXT NOT NULL,domain_id TEXT NOT NULL,action_id TEXT NOT NULL,PRIMARY KEY(requirement_id,domain_id,action_id),FOREIGN KEY(requirement_id) REFERENCES requirements(id) ON DELETE NO ACTION,FOREIGN KEY(domain_id,action_id) REFERENCES domain_actions(domain_id,id));
CREATE TABLE requirement_entities(requirement_id TEXT NOT NULL,domain_id TEXT NOT NULL,entity_id TEXT NOT NULL,PRIMARY KEY(requirement_id,domain_id,entity_id),FOREIGN KEY(requirement_id) REFERENCES requirements(id) ON DELETE NO ACTION,FOREIGN KEY(domain_id,entity_id) REFERENCES domain_entities(domain_id,id));
CREATE TABLE requirement_links(system_id TEXT NOT NULL REFERENCES requirements(id), application_id TEXT NOT NULL REFERENCES requirements(id), PRIMARY KEY(system_id,application_id));
CREATE TABLE requirement_requests(request_id TEXT PRIMARY KEY, digest TEXT NOT NULL, response TEXT NOT NULL);
CREATE TABLE requirements(id TEXT PRIMARY KEY, level TEXT NOT NULL, status TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE requirements_meta(revision INTEGER NOT NULL);
